# Mechanical delivery resizing only; all artwork is generated by image_gen.
param([ValidateSet('v2', 'v3')][string]$Version = 'v2')
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
$jobs = @(
    @{ Source = "source/cluster_bomb_sts2_${Version}_master.png"; Output = "cluster_bomb_sts2_${Version}.png" },
    @{ Source = "source/core_breakdown_sts2_${Version}_master.png"; Output = "core_breakdown_sts2_${Version}.png" }
)
foreach ($job in $jobs) {
    $sourceImage = [System.Drawing.Image]::FromFile((Join-Path $PSScriptRoot $job.Source))
    $bitmap = [System.Drawing.Bitmap]::new(500, 380, [System.Drawing.Imaging.PixelFormat]::Format24bppRgb)
    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
    $attributes = [System.Drawing.Imaging.ImageAttributes]::new()
    try {
        $graphics.CompositingMode = [System.Drawing.Drawing2D.CompositingMode]::SourceCopy
        $graphics.CompositingQuality = [System.Drawing.Drawing2D.CompositingQuality]::HighQuality
        $graphics.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $graphics.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $attributes.SetWrapMode([System.Drawing.Drawing2D.WrapMode]::TileFlipXY)
        $graphics.DrawImage($sourceImage, [System.Drawing.Rectangle]::new(0, 0, 500, 380), 0, 0,
            $sourceImage.Width, $sourceImage.Height, [System.Drawing.GraphicsUnit]::Pixel, $attributes)
        $outputPath = Join-Path $PSScriptRoot $job.Output
        $bitmap.Save($outputPath, [System.Drawing.Imaging.ImageFormat]::Png)
        [PSCustomObject]@{ File = $outputPath; Width = $bitmap.Width; Height = $bitmap.Height;
            OriginalWidth = $sourceImage.Width; OriginalHeight = $sourceImage.Height;
            Bytes = (Get-Item -LiteralPath $outputPath).Length } | ConvertTo-Json -Compress
    } finally {
        $attributes.Dispose()
        $graphics.Dispose()
        $bitmap.Dispose()
        $sourceImage.Dispose()
    }
}
